package org.vorpal.kosmos.hypercomplex.multi

import org.vorpal.kosmos.algebra.structures.CD
import org.vorpal.kosmos.core.math.Real
import org.vorpal.kosmos.hypercomplex.complex.RealComplex
import org.vorpal.kosmos.hypercomplex.complex.ComplexAlgebras
import org.vorpal.kosmos.hypercomplex.complex.complex

/**
 * The [Bicomplex] numbers, also historically known as tessarines.
 *
 * This is the commutative real 4-dimensional algebra generated by two commuting
 * imaginary units `i` and `j` with `i² = j² = -1.` Their product `k = ij` satisfies `k² = +1.`
 *
 * Representation:
 * A bicomplex number is stored in the *standard basis* as a Cayley-Dickson pair
 * ```text
 * z = z1 + z2·j,   z1, z2 ∈ ℂ(i),
 * ```
 * i.e. `𝔹 = ℂ[j]/(j² + 1)`, the Cayley-Dickson doubling of `ℂ` equipped with the *trivial*
 * involution at `σ = 1` (see [org.vorpal.kosmos.algebra.structures.CayleyDickson.commutative]).
 * All arithmetic comes from that construction; see [BicomplexAlgebras].
 *
 * [Bicomplex] is a value class rather than a typealias of `CD<RealComplex>` because the quaternions
 * `ℍ` are *also* carried by `CD<RealComplex>` (doubling `ℂ` with its *nontrivial* conjugation). The
 * two algebras share a carrier but not a multiplication, and must not be confused at the type level.
 *
 * Idempotent coordinates:
 * With the orthogonal idempotents `e₁ = (1 - k)/2`, `e₂ = (1 + k)/2`, every bicomplex number is
 * uniquely `z = 𝛂e₁ + 𝜷e₂` with
 * ```text
 * 𝛂 = z1 + i·z2,   𝜷 = z1 - i·z2,
 * ```
 * and in these coordinates multiplication is componentwise. They are exposed as the derived views
 * [alpha], [beta] and [idempotent].
 *
 * Some tessarine sources use a different basis where the unit named `j` is hyperbolic
 * rather than imaginary:
 * ```
 * i_tess² = -1, j_tess² = +1, k_tess = i_tess j_tess.
 * ```
 *
 * Under a change of basis, this is isomorphic to the present bicomplex algebra.
 *
 * The term "bibinarion" may also be used for this algebra when viewed as a
 * second binarion construction.
 */
@JvmInline
value class Bicomplex(val cd: CD<RealComplex>) {

    /** The first standard component `z1` of `z1 + z2·j`. */
    val z1: RealComplex
        get() = cd.a

    /** The second standard component `z2` of `z1 + z2·j`. */
    val z2: RealComplex
        get() = cd.b

    /** The standard real coefficients of `a + bi + cj + dk`. */
    val a: Real
        get() = z1.re
    val b: Real
        get() = z1.im
    val c: Real
        get() = z2.re
    val d: Real
        get() = z2.im

    /** The first idempotent coordinate `𝛂 = z1 + i·z2 = (a - d) + (b + c)i`. */
    val alpha: RealComplex
        get() = complex(a - d, b + c)

    /** The second idempotent coordinate `𝜷 = z1 - i·z2 = (a + d) + (b - c)i`. */
    val beta: RealComplex
        get() = complex(a + d, b - c)

    /**
     * Return the idempotent RealComplex components `(𝛂, 𝜷)` of the bicomplex number.
     */
    fun idempotent(): Pair<RealComplex, RealComplex> =
        alpha to beta

    /**
     * Return the standard RealComplex components `(z1, z2)` of the bicomplex number.
     */
    fun standard(): Pair<RealComplex, RealComplex> =
        z1 to z2

    /**
     * Returns the standard real coefficients `[a,b,c,d]`:
     * ```text
     * z = (a + bi) + (c + di)j
     * ```
     */
    fun coefficients(): List<Real> =
        listOf(a, b, c, d)

    /**
     * A bicomplex number lies in the null cone iff at least one idempotent
     * component is zero.
     *
     * Equivalently, it is not a unit, and its determinant-like norm
     * `normByConj2 = z1² + z2² = 𝛂𝜷` vanishes.
     *
     * This includes zero.
     */
    fun isInNullCone(): Boolean {
        val zero = ComplexAlgebras.ComplexField.zero
        val eq = ComplexAlgebras.eqComplexStrict
        return eq(alpha, zero) || eq(beta, zero)
    }

    /**
     * A bicomplex number is a nonzero zero divisor iff it is nonzero and lies
     * in the null cone.
     */
    fun isZeroDivisor(): Boolean =
        !isZero() && isInNullCone()

    /**
     * A bicomplex number is a unit iff it is not in the null cone.
     */
    fun isUnit(): Boolean =
        !isInNullCone()

    private fun isZero(): Boolean =
        coefficients().all { it == 0.0 }

    override fun toString(): String =
        "Bicomplex(z1=$z1, z2=$z2)"

    companion object {
        /**
         * The bicomplex number `z1 + z2·j`.
         */
        fun ofStandard(z1: RealComplex, z2: RealComplex): Bicomplex =
            Bicomplex(CD(z1, z2))

        /**
         * The bicomplex number `a + bi + cj + dk`.
         */
        fun ofStandard(a: Real, b: Real, c: Real, d: Real): Bicomplex =
            ofStandard(complex(a, b), complex(c, d))

        /**
         * The bicomplex number `𝛂e₁ + 𝜷e₂` given in idempotent coordinates:
         * ```text
         * z1 = (𝛂 + 𝜷)/2,   z2 = (𝛂 - 𝜷)/(2i).
         * ```
         */
        fun ofIdempotent(alpha: RealComplex, beta: RealComplex): Bicomplex =
            ofStandard(
                complex((alpha.re + beta.re) / 2, (alpha.im + beta.im) / 2),
                complex((alpha.im - beta.im) / 2, (beta.re - alpha.re) / 2)
            )

        val ZERO: Bicomplex = ofStandard(0.0, 0.0, 0.0, 0.0)
        val ONE: Bicomplex = ofStandard(1.0, 0.0, 0.0, 0.0)
    }
}
